1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Identity of an owner's household. Two owners live in the same household when they share
10	 * the same last name and address, compared case-insensitively with collapsed whitespace.
11	 *
12	 * <p>The {@link #id(String, String) household id} is derived deterministically from that
13	 * canonical key, so every member of a household computes the same stable identifier without
14	 * needing to coordinate.
15	 */
16	final class Household {
17	
18	    private Household() {
19	    }
20	
21	    /**
22	     * Canonical household key: last name and address, each trimmed, with internal whitespace
23	     * collapsed and lower-cased, joined so distinct pairs never collide.
24	     */
25	    static String key(String lastName, String address) {
26	        return canonical(lastName) + "\n" + canonical(address);
27	    }
28	
29	    /** Whether the two (last name, address) pairs belong to the same household. */
30	    static boolean same(String lastNameA, String addressA, String lastNameB, String addressB) {
31	        return key(lastNameA, addressA).equals(key(lastNameB, addressB));
32	    }
33	
34	    /**
35	     * Stable identifier shared by every owner in the household — the SHA-256 hex digest of the
36	     * canonical {@link #key(String, String) key}, so any member derives the same value.
37	     */
38	    static String id(String lastName, String address) {
39	        return sha256Hex(key(lastName, address));
40	    }
41	
42	    /** Case-insensitive form with leading/trailing and repeated internal whitespace collapsed. */
43	    private static String canonical(String value) {
44	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
45	    }
46	
47	    private static String sha256Hex(String value) {
48	        try {
49	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
50	            StringBuilder sb = new StringBuilder(digest.length * 2);
51	            for (byte b : digest) {
52	                sb.append(String.format("%02x", b));
53	            }
54	            return sb.toString();
55	        }
56	        catch (NoSuchAlgorithmException e) {
57	            throw new IllegalStateException("SHA-256 not available", e);
58	        }
59	    }
60	}
