3	/**
4	 * Thrown by the create-owner pipeline when another owner already shares the request's
5	 * lastName and address (compared case-insensitively with collapsed whitespace) and the
6	 * request did not opt in with {@code sharesHousehold=true}. Carries the offending lastName
7	 * so {@link DuplicateOwnerHouseholdExceptionHandler} can report it. Handled as 409 Conflict.
8	 */
9	public class DuplicateOwnerHouseholdException extends Exception {
10	
11	    private final String lastName;
12	
13	    public DuplicateOwnerHouseholdException(String lastName) {
14	        super("Owner household already in use: " + lastName);
15	        this.lastName = lastName;
16	    }
17	
18	    public String getLastName() {
19	        return this.lastName;
20	    }
21	}
