3	import net.officefloor.plugin.section.clazz.Parameter;
4	import net.officefloor.web.ObjectResponse;
5	import org.springframework.http.HttpStatus;
6	import org.springframework.http.ProblemDetail;
7	import org.springframework.http.ResponseEntity;
8	
9	/**
10	 * Responds 409 Conflict when a create request shares another owner's household (same
11	 * lastName and address) without opting in via {@code sharesHousehold}.
12	 */
13	public class DuplicateOwnerHouseholdExceptionHandler {
14	
15	    public void handle(@Parameter DuplicateOwnerHouseholdException ex,
16	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
17	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.CONFLICT,
18	                "An owner with this last name already lives at this address");
19	        response.send(ResponseEntity.status(HttpStatus.CONFLICT).body(detail));
20	    }
21	}
